import { type ParsedQs } from "qs";
import {
  requireString,
  getQueryParam,
} from "../../../rounds/query_param_utils";

export const GACHA_QUERY_KEYS = {
  BANNER: "banner",
};

export type GachaQueryParams = {
  banner?: string;
};

function useGachaQueryParams(queryParams?: ParsedQs | URLSearchParams) {
  if (!queryParams) {
    return {
      banner: undefined,
    };
  }

  const banner: string | undefined = requireString(
    getQueryParam(queryParams, GACHA_QUERY_KEYS.BANNER),
  );

  return {
    banner,
  };
}

export default useGachaQueryParams;
