import { cn } from "@hunt/styled-ui";
import { Puzzle } from "lucide-react";
import React from "react";

export type LockState = "unlockable" | "unlocked" | "locked";

export const HuntIcon = ({
  lockState = "unlocked",
  className = "",
  size = "sm",
}: {
  lockState?: LockState;
  className?: string;
  size?: "sm" | "lg";
}) => {
  if (lockState === "locked") return null;

  if (lockState === "unlockable") {
    return (
      <Puzzle
        className={cn(
          "inline-block text-blue-500",
          size === "sm" ? "h-6 w-6" : "h-12 w-12",
          className,
        )}
      />
    );
  }

  return (
    <span
      className={cn(
        `inline-block align-middle bg-contain bg-no-repeat flex-none bg-hunt-logo`,
        size === "sm" ? "w-6 h-6" : "w-12 h-12",
        className,
      )}
    />
  );
};
