import { type ParsedQs } from "qs";

/**
 * Updates the URL without causing a page reload.
 */
export function updateQueryParam(
  key: string,
  value: string,
  shouldReplace = false,
) {
  const currentUrl = new URL(window.location.href);
  const searchParams = currentUrl.searchParams;
  searchParams.set(key, value);
  if (shouldReplace) {
    window.history.replaceState({}, "", currentUrl.toString());
  } else {
    window.history.pushState({}, "", currentUrl.toString());
  }
}

export function deleteQueryParam(key: string, shouldReplace = false) {
  const currentUrl = new URL(window.location.href);
  const searchParams = currentUrl.searchParams;
  searchParams.delete(key);
  if (shouldReplace) {
    window.history.replaceState({}, "", currentUrl.toString());
  } else {
    window.history.pushState({}, "", currentUrl.toString());
  }
}

type QueryValue = undefined | null | string | ParsedQs | (string | ParsedQs)[];

export function requireString(queryValue: QueryValue) {
  if (!queryValue) {
    return undefined;
  }
  if (typeof queryValue === "string") {
    return queryValue;
  }
  console.error(
    "One of the query params in the URL path is not a valid string.",
  );
  return "";
}

export function requireBoolean(queryValue: QueryValue) {
  return requireString(queryValue) === "true";
}

export function requireNumber(queryValue: QueryValue): number | undefined {
  if (!queryValue) {
    return undefined;
  }
  if (typeof queryValue === "string" && !isNaN(Number(queryValue))) {
    return Number(queryValue);
  }
  console.error(
    "One of the query params in the URL path cannot be converted to a number.",
  );
  return undefined;
}

export function getQueryParam(
  queryParams: ParsedQs | URLSearchParams,
  key: string,
) {
  return queryParams instanceof URLSearchParams
    ? queryParams.get(key)
    : queryParams[key];
}
