function getQuestBannerSlug(questSlug: string): string | undefined {
  if (questSlug.startsWith("hourlies-")) {
    return "hourlies";
  }
  if (questSlug.startsWith("meta-")) {
    return "meta";
  }
  const markerIndex = questSlug.indexOf("-quest-");
  if (markerIndex > 0) {
    return questSlug.slice(0, markerIndex);
  }
  return undefined;
}

function formatHintUnlockDelay(hours: number) {
  const unit = Math.abs(hours) === 1 ? "hour" : "hours";
  const value = Number.isInteger(hours) ? hours.toString() : `${hours}`;
  return `${value} ${unit}`;
}

const FREE_ANSWERS_OPEN_EVENT = "free-answers-open";

const ActivityLogLinkToneContext = createContext<"default" | "notification">(
  "default",
);

const ActivityLogLink: React.FC<
  React.AnchorHTMLAttributes<HTMLAnchorElement>
> = ({ children, className, href, onClick, ...props }) => {
  const handleClick = (e: React.MouseEvent<HTMLAnchorElement>) => {
    // For Monarch links, we want to update the URL without page reload for better performance.
    if (href?.includes("showMonarch=true") && typeof window !== "undefined") {
      e.preventDefault();

      const url = new URL(window.location.href);
      url.searchParams.set("showMonarch", "true");

      // Extract puzzmonSlug from the href.
      const puzzmonSlugMatch = /puzzmonSlug=([^&]+)/.exec(href);
      if (puzzmonSlugMatch) {
        url.searchParams.set("puzzmonSlug", puzzmonSlugMatch[1]);
      }

      // Update the URL.
      window.history.pushState({}, "", url.toString());
      // Dispatch custom event to notify the EmbeddedMonarch component.
      window.dispatchEvent(new CustomEvent("monarch-open"));
    }

    onClick?.(e);
  };

  const tone = useContext(ActivityLogLinkToneContext);
  const baseClasses =
    tone === "notification"
      ? "no-underline hover:underline text-[var(--notification-link-color)] visited:text-[var(--notification-link-color)] hover:text-[var(--notification-link-color)]"
      : "no-underline text-accent hover:text-accent hover:underline";

  return (
    <a
      {...props}
      className={cn(baseClasses, className)}
      href={href}
      onClick={handleClick}
    >
      {children}
    </a>
  );
};

const FreeAnswersLink: React.FC<{
  count?: number;
}> = ({ count }) => {
  const label = count === 1 ? "free answer" : "free answers";
  return (
    <ActivityLogLink
      href="#"
      onClick={(e) => {
        e.preventDefault();
        if (typeof window !== "undefined") {
          window.dispatchEvent(new CustomEvent(FREE_ANSWERS_OPEN_EVENT));
        }
      }}
    >
      {label}
    </ActivityLogLink>
  );
};

const CutsceneLink: React.FC<{
  cutscene: string;
  darkTextStyling?: boolean;
}> = ({ cutscene, darkTextStyling = false }) => {
  return (
    <div
      className={cn("mt-1", darkTextStyling ? "text-secondary" : "text-white")}
    >
      Watch the{" "}
      <ActivityLogLink href={`/story?cutscene=${cutscene}`}>
        cutscene
      </ActivityLogLink>
      .
    </div>
  );
};

type ActivityLogEntryDisplay = {
  icon: React.ReactNode;
  description: React.ReactNode;
  showNotification: boolean;
};

const HIDDEN_ROUNDS = [
  "research_tasks",
  "kingdom_of_the_puzzmon",
  "end_game",
  "events",
  "floaters",
];

// Exclude puzzle_unlockable entries for these puzzles.
const GACHA_PUZZLE_SLUGS = [
  "meme_scenes",
  "common_scenes",
  "charfactor",
  "as_the_fly_crows",
  "building_blocks",
  "easy_as_1_22_333",
  "plots",
  "graphs",
  "hear_me_out",
  "goku",
  "to_pull_or_not_to_pull",
];

export function formatActivityLogEntry(
  entry: ActivityLogEntry,
  isNotification = false,
  teamState?: TeamHuntState,
): ActivityLogEntryDisplay | null {
  const getBannerRoundPath = (bannerSlug: string) =>
    `/rounds/fates_thread_casino?banner=${encodeURIComponent(bannerSlug)}`;

  const wrapDescription = (node: React.ReactNode) =>
    isNotification ? (
      <ActivityLogLinkToneContext.Provider value="notification">
        {node}
      </ActivityLogLinkToneContext.Provider>
    ) : (
      node
    );

  const wrapEntry = (
    value: ActivityLogEntryDisplay,
  ): ActivityLogEntryDisplay =>
    isNotification
      ? { ...value, description: wrapDescription(value.description) }
      : value;

  const getHintResourcePagePath = (hintResource: HintResource) => {
    switch (hintResource.type) {
      case "puzzle":
        return `/puzzles/${hintResource.slug}`;
      case "round":
        return `/rounds/${hintResource.slug}`;
      case "banner":
        return getBannerRoundPath(hintResource.slug);
      default:
        return undefined;
    }
  };

  switch (entry.type) {
    case "currency_adjusted":
      return wrapEntry({
        icon: (
          <FlaskConical
            className={cn(
              "block text-rp mx-auto",
              isNotification ? "h-12 w-12" : "h-6 w-6",
            )}
            aria-hidden="true"
          />
        ),
        description: <>Received {entry.currency_delta} RP</>,
        showNotification: true,
      });
    case "round_unlockable":
      return wrapEntry({
        icon: (
          <ExclamationMark
            className={cn(
              "fill-accent",
              isNotification ? "h-12 w-12" : "h-6 w-6",
            )}
          />
        ),
        description: <>Discovered round {entry.title}</>,
        showNotification: true,
      });
    case "round_unlocked": {
      if (HIDDEN_ROUNDS.includes(entry.slug)) {
        return null;
      }

      const watchCutsceneInstruction = entry.has_unlocked_cutscene && (
        <CutsceneLink cutscene={`${entry.slug}_intro`} />
      );

      return wrapEntry({
        icon: (
          <ExclamationMark
            className={cn(
              "fill-accent",
              isNotification ? "h-12 w-12" : "h-6 w-6",
            )}
          />
        ),
        description: (
          <>
            Unlocked round{" "}
            <ActivityLogLink href={`/rounds/${entry.slug}`}>
              {entry.title}
            </ActivityLogLink>
            {watchCutsceneInstruction}
          </>
        ),
        showNotification: true,
      });
    }
    case "puzzle_unlockable": {
      if (GACHA_PUZZLE_SLUGS.includes(entry.slug)) {
        return null;
      }
      // isNotification just sets the text color. All other notifications are
      // on a green background, but this is on a blue background and we'll use
      // the isNotification = false styling.
      const watchCutsceneInstruction = entry.has_unlocked_cutscene && (
        <CutsceneLink cutscene={`artifacts_intro`} />
      );

      return wrapEntry({
        icon: (
          <ExclamationMark
            className={cn(
              "fill-accent",
              isNotification ? "h-12 w-12" : "h-6 w-6",
            )}
          />
        ),
        description: (
          <>
            Discovered puzzle {entry.title} {watchCutsceneInstruction}
          </>
        ),
        showNotification: true,
      });
    }
    case "puzzle_unlocked":
      if (entry.is_task) {
        return wrapEntry({
          icon: (
            <PuzzleIconFromState
              state="unlocked"
              className={cn("text-accent")}
              size={isNotification ? "lg" : "sm"}
              isResearchTask
            />
          ),
          description: (
            <>
              Unlocked task{" "}
              <ActivityLogLink href={`/research_tasks/${entry.slug}`}>
                {entry.title}
              </ActivityLogLink>
            </>
          ),
          showNotification: true,
        });
      } else {
        const watchIntroCutsceneInstruction = entry.has_unlocked_cutscene && (
          <CutsceneLink cutscene={`${entry.slug}_intro`} />
        );

        return wrapEntry({
          icon: (
            <PuzzleIconFromState
              state="unlocked"
              className={cn("text-accent")}
              size={isNotification ? "lg" : "sm"}
            />
          ),
          description: (
            <>
              Unlocked puzzle{" "}
              <ActivityLogLink href={`/puzzles/${entry.slug}`}>
                {entry.title}
              </ActivityLogLink>
              {watchIntroCutsceneInstruction}
            </>
          ),
          showNotification: true,
        });
      }
    case "puzzle_partially_solved":
      return wrapEntry({
        icon: (
          <FlaskConical
            className={cn(
              "block text-rp mx-auto",
              isNotification ? "h-12 w-12" : "h-6 w-6",
            )}
            aria-hidden="true"
          />
        ),
        description: (
          <>
            Partially solved puzzle{" "}
            <ActivityLogLink href={`/puzzles/${entry.slug}`}>
              {entry.title}
            </ActivityLogLink>{" "}
            (partial answer <code>{entry.partial}</code>)
          </>
        ),
        showNotification: true,
      });
    case "puzzle_solved": {
      const additionalInstructions = entry.additional_instructions && (
        <div
          className={cn(
            "mt-1 text-sm",
            isNotification ? "text-secondary" : "text-amber-100",
          )}
        >
          {entry.additional_instructions}
        </div>
      );

      const watchOutroCutsceneInstruction = entry.has_unlocked_cutscene &&
        !entry.is_task &&
        entry.round_slug && (
          <CutsceneLink
            cutscene={
              entry.cutscene_id_override
                ? `${entry.cutscene_id_override}_outro`
                : `${entry.round_slug}_outro`
            }
            darkTextStyling={isNotification}
          />
        );

      if (entry.is_task) {
        return wrapEntry({
          icon: (
            <PuzzleIconFromState
              state="solved"
              isResearchTask
              size={isNotification ? "lg" : "sm"}
            />
          ),
          description: (
            <>
              Completed task{" "}
              <ActivityLogLink href={`/research_tasks/${entry.slug}`}>
                {entry.title}
              </ActivityLogLink>
              {additionalInstructions}
            </>
          ),
          showNotification: true,
        });
      } else {
        return wrapEntry({
          icon: (
            <PuzzleIcon
              lockState="unlocked"
              solved={!!entry.answer}
              size={isNotification ? "lg" : "sm"}
            />
          ),
          description: (
            <>
              Solved puzzle{" "}
              <ActivityLogLink href={`/puzzles/${entry.slug}`}>
                {entry.title}
              </ActivityLogLink>{" "}
              (answer <code>{entry.answer}</code>)
              {entry.puzzmon_slug && entry.puzzmon_name && (
                <>
                  {" "}
                  and befriended{" "}
                  <ActivityLogLink
                    // This does not actually trigger the link. We include this so that the link shows a link preview,
                    // but the ActivityLogLink component handles the redirect via Javascript for better performance.
                    href={`${typeof window !== "undefined" ? window.location.pathname : "/activity_log"}?showMonarch=true&puzzmonSlug=${entry.puzzmon_slug}`}
                  >
                    {entry.puzzmon_name}
                  </ActivityLogLink>
                </>
              )}
              {watchOutroCutsceneInstruction}
              {additionalInstructions}
            </>
          ),
          showNotification: true,
        });
      }
    }
    case "interaction_unlocked":
      return wrapEntry({
        icon: (
          <HuntIcon
            className={isNotification ? "transform-gpu drop-shadow-md" : ""}
            size={isNotification ? "lg" : "sm"}
          />
        ),
        description: (
          <>
            Unlocked interaction{" "}
            <ActivityLogLink href={`/interactions/${entry.slug}`}>
              {entry.title}
            </ActivityLogLink>
          </>
        ),
        showNotification: !entry.virtual,
      });
    case "interaction_started":
      return wrapEntry({
        icon: (
          <HuntIcon
            className={isNotification ? "transform-gpu drop-shadow-md" : ""}
            size={isNotification ? "lg" : "sm"}
          />
        ),
        description: (
          <>
            Started interaction{" "}
            <ActivityLogLink href={`/interactions/${entry.slug}`}>
              {entry.title}
            </ActivityLogLink>
          </>
        ),
        showNotification: false,
      });
    case "interaction_completed":
      return wrapEntry({
        icon: (
          <HuntIcon
            className={isNotification ? "transform-gpu drop-shadow-md" : ""}
            size={isNotification ? "lg" : "sm"}
          />
        ),
        description: (
          <>
            Completed interaction{" "}
            <ActivityLogLink href={`/interactions/${entry.slug}`}>
              {entry.title}
            </ActivityLogLink>
          </>
        ),
        showNotification: false,
      });
    case "gate_completed":
      if (!entry.title) {
        return null;
      }
      if (entry.slug.endsWith(":tile-level-solved")) {
        return wrapEntry({
          icon: <PuzzleIcon lockState="unlocked" solved />,
          description: (
            <>
              Completed level{" "}
              <ActivityLogLink href={`/rounds/atlas_of_mosaics`}>
                {entry.title}
              </ActivityLogLink>
            </>
          ),
          showNotification: entry.show_notification,
        });
      }
      if (
        entry.slug.startsWith("gacha_banner_") &&
        entry.slug.endsWith("_unlocked")
      ) {
        const bannerSlug = entry.slug.slice(
          "gacha_banner_".length,
          -"_unlocked".length,
        );
        const bannerName = entry.title;
        return wrapEntry({
          icon: (
            <LandPlot
              className={cn(
                "stroke-accent",
                isNotification ? "h-12 w-12" : "h-6 w-6",
              )}
            />
          ),
          description: (
            <>
              Unlocked banner{" "}
              <ActivityLogLink href={getBannerRoundPath(bannerSlug)}>
                {bannerName}
              </ActivityLogLink>
            </>
          ),
          showNotification: entry.show_notification,
        });
      }
      return null;
    case "rate_limits_reset":
      return wrapEntry({
        icon: "⏰",
        description: (
          <>
            Rate limits reset for puzzle{" "}
            <ActivityLogLink href={`/puzzles/${entry.slug}`}>
              {entry.title}
            </ActivityLogLink>
          </>
        ),
        showNotification: false,
      });
    case "strong_currency_adjusted":
      return wrapEntry({
        icon: (
          <Gift
            className={cn(
              "text-accent",
              isNotification ? "h-12 w-12" : "h-6 w-6",
            )}
          />
        ),
        description: (
          <>
            {entry.strong_currency_delta}{" "}
            <FreeAnswersLink count={entry.strong_currency_delta} />{" "}
            {entry.strong_currency_delta === 1 ? "was" : "were"} granted
          </>
        ),
        showNotification: true,
      });
    case "strong_currency_exchanged":
      return wrapEntry({
        icon: (
          <Gift
            className={cn(
              "text-accent",
              isNotification ? "h-12 w-12" : "h-6 w-6",
            )}
          />
        ),
        description: <>Exchanged 1 free answer for {entry.currency_delta} RP</>,
        showNotification: true,
      });
    case "puzzle_answer_bought":
      return wrapEntry({
        icon: (
          <Gift
            className={cn(
              "text-accent",
              isNotification ? "h-12 w-12" : "h-6 w-6",
            )}
          />
        ),
        description: (
          <>
            Exchanged 1 free answer for the answer to puzzle{" "}
            <ActivityLogLink href={`/puzzles/${entry.slug}`}>
              {entry.title}
            </ActivityLogLink>
            : <code>{entry.answer}</code>
          </>
        ),
        showNotification: true,
      });
    case "erratum_issued": {
      const erratumResource =
        entry.erratum_resource ??
        ({ type: "puzzle", slug: entry.slug } as const);
      const resourceTitle = entry.resource_title ?? erratumResource.slug;
      const content = entry.content;
      let href: string | undefined;
      switch (erratumResource.type) {
        case "puzzle":
          href = `/puzzles/${erratumResource.slug}`;
          break;
        case "task":
          href = `/research_tasks/${erratumResource.slug}`;
          break;
        case "round":
          href = `/rounds/${erratumResource.slug}`;
          break;
        case "clue":
          href = `/rounds/fates_thread_casino/clue/${erratumResource.slug}`;
          break;
        case "quest":
          {
            const bannerSlug = getQuestBannerSlug(erratumResource.slug);
            href = bannerSlug
              ? `/rounds/fates_thread_casino/quests?${GACHA_QUERY_KEYS.BANNER}=${bannerSlug}`
              : "/rounds/fates_thread_casino/quests";
          }
          break;
        case "tile_level":
          href = "/rounds/atlas_of_mosaics";
          break;
      }
      const link =
        href !== undefined ? (
          <ActivityLogLink href={href}>{resourceTitle}</ActivityLogLink>
        ) : (
          resourceTitle
        );
      return wrapEntry({
        icon: (
          <FilePenLine
            className={cn(
              "text-rose-500",
              isNotification ? "h-12 w-12" : "h-6 w-6",
            )}
          />
        ),
        description: (
          <>
            Erratum issued for {link}
            {content ? <>: {content}</> : null}
          </>
        ),
        showNotification: entry.show_notification ?? true,
      });
    }
    case "global_hints_unlocked": {
      const hintResource =
        entry.hint_resource ?? ({ type: "puzzle", slug: entry.slug } as const);
      const resourceHref = getHintResourcePagePath(hintResource);
      const resourceTitle = entry.resource_title ?? hintResource.slug;
      const resourceLink = resourceHref ? (
        <ActivityLogLink href={resourceHref}>{resourceTitle}</ActivityLogLink>
      ) : (
        resourceTitle
      );
      let description: React.ReactNode;

      if (teamState) {
        let hintsUnlockedAt: string | undefined;
        switch (hintResource.type) {
          case "puzzle":
            hintsUnlockedAt =
              teamState.puzzles[hintResource.slug]?.hints_unlocked_at;
            break;
          case "round":
            hintsUnlockedAt =
              teamState.rounds[hintResource.slug]?.hints_unlocked_at;
            break;
          default:
            hintsUnlockedAt = undefined;
        }

        const hintsAvailableAt = hintsUnlockedAt
          ? new Date(hintsUnlockedAt)
          : undefined;
        const hintsAvailableAtMs = hintsAvailableAt?.getTime();

        if (
          hintsAvailableAt &&
          hintsAvailableAtMs !== undefined &&
          !Number.isNaN(hintsAvailableAtMs) &&
          hintsAvailableAtMs > Date.now()
        ) {
          const hintAvailableAt = hintsAvailableAt.toLocaleString("en-US");
          description = (
            <>
              Hints will be available for {resourceLink} at {hintAvailableAt}
            </>
          );
        } else {
          description = <>Hints are now available for {resourceLink}</>;
        }
      } else {
        const delay = formatHintUnlockDelay(entry.minimum_unlock_hours ?? 0);
        description = (
          <>
            Hints are now released for {resourceLink}
            {entry.minimum_unlock_hours && entry.minimum_unlock_hours > 0 ? (
              <> ({delay} after unlock)</>
            ) : null}
          </>
        );
      }

      return wrapEntry({
        icon: (
          <Lightbulb
            className={cn(
              "stroke-accent",
              isNotification ? "h-12 w-12" : "h-6 w-6",
            )}
          />
        ),
        description,
        showNotification: true,
      });
    }
    case "hint_requested": {
      const hintResource =
        entry.hint_resource ?? ({ type: "puzzle", slug: entry.slug } as const);
      const resourceTitle = entry.resource_title ?? hintResource.slug;
      const resourceHref = getHintResourceHintsPath(hintResource);
      return wrapEntry({
        icon: (
          <Lightbulb
            className={cn(
              "stroke-accent",
              isNotification ? "h-12 w-12" : "h-6 w-6",
            )}
          />
        ),
        description: (
          <>
            Requested a hint for{" "}
            {resourceHref ? (
              <ActivityLogLink href={resourceHref}>
                {resourceTitle}
              </ActivityLogLink>
            ) : (
              resourceTitle
            )}
          </>
        ),
        showNotification: false,
      });
    }
    case "hint_responded": {
      const hintResource =
        entry.hint_resource ?? ({ type: "puzzle", slug: entry.slug } as const);
      const resourceTitle = entry.resource_title ?? hintResource.slug;
      const resourceHref = getHintResourceHintsPath(hintResource);
      return wrapEntry({
        icon: (
          <Lightbulb
            className={cn(
              "stroke-accent",
              isNotification ? "h-12 w-12" : "h-6 w-6",
            )}
          />
        ),
        description: (
          <>
            Hint provided for{" "}
            {resourceHref ? (
              <ActivityLogLink href={resourceHref}>
                {resourceTitle}
              </ActivityLogLink>
            ) : (
              resourceTitle
            )}
          </>
        ),
        showNotification: true,
      });
    }
    case "overworld_max_width_set": {
      return null;
    }
    case "teams_notified": {
      // Parse markdown-style links [text](url) in the message
      const parseMessageWithLinks = (message: string) => {
        const parts: React.ReactNode[] = [];
        let lastIndex = 0;
        const linkRegex = /\[([^\]]+)\]\(([^)]+)\)/g;
        let match;

        while ((match = linkRegex.exec(message)) !== null) {
          // Add text before the link
          if (match.index > lastIndex) {
            parts.push(message.substring(lastIndex, match.index));
          }
          // Add the link
          parts.push(
            <ActivityLogLink key={match.index} href={match[2]}>
              {match[1]}
            </ActivityLogLink>,
          );
          lastIndex = match.index + match[0].length;
        }

        // Add remaining text after the last link
        if (lastIndex < message.length) {
          parts.push(message.substring(lastIndex));
        }

        return parts.length > 0 ? parts : message;
      };

      return wrapEntry({
        icon: (
          <Info
            className={cn(
              "stroke-accent",
              isNotification ? "h-12 w-12" : "h-6 w-6",
            )}
          />
        ),
        description: <>{parseMessageWithLinks(entry.message)}</>,
        showNotification: true,
      });
    }
  }

  return null;
}

type PuzzleUnlockableEntry = Extract<
  ActivityLogEntry,
  {
    type: "puzzle_unlockable";
  }
>;

const PuzzleDiscoveryDescription = ({
  entry,
}: {
  entry: PuzzleUnlockableEntry;
}) => {
  const teamState = useTeamState();
  const puzzle = teamState.puzzles[entry.slug];
  const metadata = useMemo(() => getPuzzleMetadata(entry.slug), [entry.slug]);
  const puzzleDesc = metadata?.desc;
  const puzzleNsfw = metadata?.nsfw;
  const physicalPresenceRequirement = metadata?.physical_presence_requirement;

  const puzzleStateHandle = usePuzzleState(teamState.epoch, {
    slug: entry.slug,
    title: entry.title,
    state: puzzle?.locked ?? "unlockable",
    answer: puzzle?.answer,
    solved: puzzle?.solved,
    desc: puzzleDesc,
    unlock_cost: puzzle?.unlock_cost,
    is_overworld_feeder: puzzle?.is_overworld_feeder ?? false,
  });
  const [puzzleState] = puzzleStateHandle;
  const modalRef = React.useRef<HTMLDialogElement>(null);
  const handleUnlockClick = React.useCallback(() => {
    modalRef.current?.showModal();
  }, []);
  const dismissModal = React.useCallback(() => {
    modalRef.current?.close();
  }, []);
  const watchCutsceneInstruction = entry.has_unlocked_cutscene && (
    <CutsceneLink cutscene={`artifacts_intro`} />
  );

  if (!puzzle) {
    return (
      <>
        Discovered puzzle {entry.title} {watchCutsceneInstruction}
      </>
    );
  }

  if (puzzleState.state === "unlocked") {
    return (
      <>
        Discovered puzzle{" "}
        <ActivityLogLink href={`/puzzles/${entry.slug}`}>
          {entry.title}
        </ActivityLogLink>
        {watchCutsceneInstruction}
      </>
    );
  }

  if (puzzleState.state === "unlockable") {
    if (IS_STATIC_SITE) {
      return (
        <>
          Discovered puzzle {entry.title}
          {watchCutsceneInstruction}
        </>
      );
    }
    const cost = puzzleState.unlock_cost ?? 1;
    return (
      <>
        Discovered puzzle{" "}
        <button
          type="button"
          className={cn(
            "no-underline text-accent hover:text-accent hover:underline",
            "bg-transparent border-0 p-0 font-inherit cursor-pointer",
          )}
          onClick={handleUnlockClick}
        >
          {entry.title}
        </button>
        <PuzzleUnlockModal
          ref={modalRef}
          cost={cost}
          stateHandle={puzzleStateHandle}
          onDismiss={dismissModal}
          physicalPresenceRequirement={physicalPresenceRequirement}
          nsfw={puzzleNsfw}
        />
        {watchCutsceneInstruction}
      </>
    );
  }

  return <>Discovered puzzle {entry.title}</>;
};

const ActivityLogItem = ({
  entry,
  resultingCurrencyBalance,
}: {
  entry: ActivityLogEntry;
  resultingCurrencyBalance: number;
}) => {
  const teamState = useTeamState();
  const formatted = formatActivityLogEntry(entry, false, teamState);
  if (!formatted) {
    return null;
  }

  const maybeCurrencyText =
    entry.currency_delta !== 0
      ? entry.currency_delta > 0
        ? `+${entry.currency_delta}`
        : `${entry.currency_delta}`
      : undefined;

  const timestamp = new Date(entry.timestamp);
  const formattedTimestamp = timestamp.toLocaleString();
  const formattedTimestampShort = timestamp.toLocaleString("en-US", {
    month: "numeric",
    day: "numeric",
    hour: "numeric",
    minute: "2-digit",
  });
  let descriptionNode = formatted.description;

  if (entry.type === "puzzle_unlockable") {
    descriptionNode = <PuzzleDiscoveryDescription entry={entry} />;
  }

  return (
    <tr className="odd:bg-white/[0.08] even:bg-white/[0.04] text-base text-white">
      <td className="px-4 sm:px-5 lg:px-6 py-3 font-nova text-white/90 whitespace-nowrap">
        <span className="hidden lg:inline">{formattedTimestamp}</span>
        <span className="lg:hidden">{formattedTimestampShort}</span>
      </td>
      <td className="px-4 py-3 text-lg text-center align-middle min-w-[2.5rem]">
        {formatted.icon}
      </td>
      <td className="px-6 py-3 font-nova text-white/90">{descriptionNode}</td>
      <td className="px-4 py-3 text-right font-mono text-base text-white whitespace-nowrap">
        {maybeCurrencyText}
      </td>
      <td className="px-4 py-3 text-right font-mono text-base text-white whitespace-nowrap">
        {resultingCurrencyBalance}
      </td>
    </tr>
  );
};

const ActivityLog = ({ logs }: { logs: ActivityLogEntry[] }) => {
  const [sortDesc, setSortDesc] = React.useState(true);

  const filteredLogs = useMemo(() => {
    return logs.filter(
      (log) =>
        log.type !== "interaction_unlocked" &&
        log.type !== "interaction_completed" &&
        log.type !== "interaction_started",
    );
  }, [logs]);

  useEffect(() => {
    if (window.localStorage.getItem("activityLogSortDesc") === "false") {
      setSortDesc(false);
    }
  }, []);

  const lastLogLength = React.useRef(filteredLogs.length);
  useEffect(() => {
    if (
      !sortDesc &&
      filteredLogs.length > lastLogLength.current &&
      window.scrollY + window.innerHeight > document.body.scrollHeight - 250
    ) {
      window.scrollTo({
        left: 0,
        top: document.body.scrollHeight,
        behavior: "smooth",
      });
    }
    lastLogLength.current = filteredLogs.length;
  }, [filteredLogs, sortDesc]);

  function toggleSort() {
    setSortDesc(!sortDesc);
    window.localStorage.setItem("activityLogSortDesc", String(!sortDesc));
  }

  if (filteredLogs.length === 0) {
    return (
      <div className="text-gray-700 dark:text-gray-300">No activity yet.</div>
    );
  }

  let currencyAccumulator = 0;
  const rows = filteredLogs.map((entry) => {
    currencyAccumulator += entry.currency_delta;
    return (
      <ActivityLogItem
        key={entry.id}
        entry={entry}
        resultingCurrencyBalance={currencyAccumulator}
      />
    );
  });

  if (sortDesc) {
    rows.reverse();
  }

  return (
    <div className="mt-6 w-full max-w-4xl mx-auto rounded-3xl overflow-hidden border-2 border-secondary bg-primary">
      <div className="overflow-x-auto">
        <table className="w-full table-fixed text-left font-sans text-white">
          <colgroup>
            <col style={{ width: "30%" }} />
            <col style={{ width: "6%" }} />
            <col style={{ width: "44%" }} />
            <col style={{ width: "10%" }} />
            <col style={{ width: "10%" }} />
          </colgroup>
          <thead>
            <tr className="bg-secondary text-white text-lg font-nova">
              <th
                onClick={toggleSort}
                role="button"
                className="px-4 sm:px-5 lg:px-6 py-3 cursor-pointer text-left"
              >
                <span className="inline-flex items-center gap-2">
                  Time
                  {sortDesc ? (
                    <ChevronDown className="h-4 w-4" aria-hidden="true" />
                  ) : (
                    <ChevronUp className="h-4 w-4" aria-hidden="true" />
                  )}
                </span>
              </th>
              <th className="px-4 py-3 text-center min-w-[2.5rem]">Type</th>
              <th className="px-6 py-3 text-left">Event</th>
              <th className="px-4 py-3 text-right">
                <span className="inline-flex w-full items-center justify-end gap-2">
                  <FlaskConical
                    className="h-5 w-5 text-rp shrink-0"
                    aria-hidden="true"
                  />
                  <span>change</span>
                </span>
              </th>
              <th className="px-4 py-3 text-right">
                <span className="inline-flex w-full items-center justify-end gap-2">
                  <FlaskConical
                    className="h-5 w-5 text-rp shrink-0"
                    aria-hidden="true"
                  />
                  <span>total</span>
                </span>
              </th>
            </tr>
          </thead>
          <tbody>{rows}</tbody>
        </table>
      </div>
    </div>
  );
};

export default ActivityLog;
