import { type HintResource } from "@hunt/public-client";

export function getHintResourceHintsPath(
  hintResource: HintResource,
): string | undefined {
  switch (hintResource.type) {
    case "puzzle":
      return `/puzzles/${hintResource.slug}/hints`;
    case "round":
      return `/rounds/${hintResource.slug}/hints`;
    case "banner":
      return `/rounds/fates_thread_casino/hints?banner=${encodeURIComponent(hintResource.slug)}`;
    default:
      return undefined;
  }
}

export function getHintResourceHintsUrl(
  baseUrl: string,
  hintResource: HintResource,
): string | undefined {
  const path = getHintResourceHintsPath(hintResource);
  return path ? `${baseUrl}${path}` : undefined;
}
